components.css:
.ds-nav{background:var(--navy,#1c2942);padding:12px;display:flex;flex-direction:column;gap:2px;}.ds-nav button{font-family:'IBM Plex Sans',sans-serif;font-size:13px;letter-spacing:-.01em;font-weight:400;line-height:18px;text-align:left;min-height:32px;padding:4px 12px;border:0;border-radius:6px;background:transparent;color:var(--rail-text);cursor:pointer;transition:background 80ms ease-out,color 80ms ease-out,border-color 80ms ease-out;}.ds-nav button:hover{background:#2a3953;}.ds-nav button[aria-current=page]{background:var(--selected-context);color:var(--ink);}.ds-nav button:focus-visible{outline:2px solid var(--apricot);outline-offset:2px;}@media(max-width:700px){.ds-nav button{min-height:36px;}}@media(prefers-reduced-motion:reduce){.ds-nav button{transition:none;}}
.ds-nav{background:linear-gradient(155deg,var(--accent) -45%,var(--navy) 36%,var(--navy-deep) 100%);color:var(--rail-text);border-right:1px solid var(--navy-deep);box-shadow:inset 1px 0 0 color-mix(in srgb,var(--rail-text) 12%,transparent),inset -1px 0 0 var(--rail-line)!important;backdrop-filter:none;--scroll-thumb:#66738a;--scroll-track:var(--navy)}
.ds-nav button[aria-current=page]{background:var(--selected-context);background-image:linear-gradient(180deg,color-mix(in srgb,var(--white) 44%,transparent),transparent 65%,color-mix(in srgb,var(--apricot) 22%,transparent));color:var(--ink);box-shadow:inset 0 1px 0 var(--white),inset 0 -1px 0 color-mix(in srgb,var(--apricot-ink) 26%,var(--selected-context)),0 2px 5px color-mix(in srgb,var(--navy-deep) 45%,transparent)!important;background-size:100% 140%;animation:nav-seat 120ms ease-out}
@keyframes nav-seat{from{background-position:0 100%}to{background-position:0 0}}
@media(prefers-reduced-motion:reduce){.ds-nav button{transition:none!important;animation:none!important}}
@media(forced-colors:active){.ds-nav,.ds-nav button{background-image:none!important;box-shadow:none!important;animation:none!important}}
